-- 20261112h (SRS-5.1zzzzzzz438): nhãn ô riêng đi cùng dữ liệu `listing_noi_bo.du_lieu->'_nhan'` (ô → tên, lõi ghi từ FIELD_LABELS mỗi lần
-- lưu tin — `supabase_store._ghi_noi_bo`). Trang admin hiện đúng các ô có trong `_nhan`, không giữ danh sách riêng. Bản này chỉ nạp `_nhan` cho
-- các dòng lưu trước khi lõi ghi nó; bản đồ nhãn sinh từ lõi lúc viết migration (một lần), dòng mới do lõi tự ghi.
update public.listing_noi_bo n
   set du_lieu = n.du_lieu || jsonb_build_object('_nhan', (
         select jsonb_object_agg(k, v) from jsonb_each_text('{"chia_khoa": "khi dẫn khách xem thì liên hệ ai, ai giữ chìa khoá", "dong_y_ban": "người đứng tên sổ đã đồng ý ký bán chưa", "du_kien_hoan_cong": "chủ dự kiến khi nào hoàn công xong", "du_kien_ra_so": "dự kiến khi nào có sổ / sang tên xong", "dung_ten_so": "người đứng tên sổ", "gio_xem": "khung giờ tiện dẫn khách xem nhà", "han_cong_chung": "ngày / hạn hẹn ra công chứng sang tên", "ly_do_ban": "lý do cần bán / bán gấp hay thong thả", "ngay_coc": "ngày khách mua đặt cọc", "so_goc": "đất gốc của căn giấy tay đã có sổ chưa", "tien_coc": "số tiền khách mua đã đặt cọc cho căn"}'::jsonb) m(k, v) where n.du_lieu ? m.k))
 where not n.du_lieu ? '_nhan'
   and exists (select 1 from jsonb_object_keys('{"chia_khoa": "khi dẫn khách xem thì liên hệ ai, ai giữ chìa khoá", "dong_y_ban": "người đứng tên sổ đã đồng ý ký bán chưa", "du_kien_hoan_cong": "chủ dự kiến khi nào hoàn công xong", "du_kien_ra_so": "dự kiến khi nào có sổ / sang tên xong", "dung_ten_so": "người đứng tên sổ", "gio_xem": "khung giờ tiện dẫn khách xem nhà", "han_cong_chung": "ngày / hạn hẹn ra công chứng sang tên", "ly_do_ban": "lý do cần bán / bán gấp hay thong thả", "ngay_coc": "ngày khách mua đặt cọc", "so_goc": "đất gốc của căn giấy tay đã có sổ chưa", "tien_coc": "số tiền khách mua đã đặt cọc cho căn"}'::jsonb) k where n.du_lieu ? k);
